function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke()}}

function flameShape(x,y,size,phase){ctx.save();ctx.translate(x,y);ctx.rotate(phase*.2);poly([[-size*.6,size*.4],[-size*.8,-size*.1],[-size*.2,-size*.6],[0,-size*1.5],[size*.3,-size*.45],[size*.7,-size*.7],[size*.6,size*.4]],'#f66b1d');poly([[-size*.3,size*.35],[-size*.4,-size*.3],[0,-size],[size*.35,-size*.1],[size*.25,size*.3]],'#ffcd3e');poly([[-size*.12,size*.3],[0,-size*.55],[size*.15,size*.25]],'#fff7b4');ctx.restore()}

function leafShape(x,y,size,a){ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.beginPath();ctx.moveTo(-size,0);ctx.quadraticCurveTo(0,-size*.9,size,0);ctx.quadraticCurveTo(0,size*.9,-size,0);ctx.fillStyle='#76d649';ctx.fill();line(-size,0,size,0,'#d4fb89',1.5);ctx.restore()}

function lightning(x,y,x2,y2,seed,width=4){let dx=x2-x,dy=y2-y,len=Math.hypot(dx,dy)||1;ctx.beginPath();ctx.moveTo(x,y);let pts=[];for(let i=1;i<=9;i++){let j=i===9?0:Math.sin(i*37+seed)*13,xx=x+dx*i/9-dy/len*j,yy=y+dy*i/9+dx/len*j;ctx.lineTo(xx,yy);pts.push([xx,yy])}ctx.strokeStyle='#f5a529';ctx.lineWidth=width+7;ctx.stroke();ctx.strokeStyle='#fff074';ctx.lineWidth=width+3;ctx.stroke();ctx.strokeStyle='#fffef3';ctx.lineWidth=width;ctx.stroke();for(let i of [2,5]){let [xx,yy]=pts[i];line(xx,yy,xx+Math.sin(seed+i)*23,yy-23,'#ffed7a',2)}}

function drawAttack(s){ctx.save();ctx.globalCompositeOperation='source-over';let t=motionClock,dx=s.x-s.ox,dy=s.y-s.oy,len=Math.hypot(dx,dy)||1,tail=Math.min(len,200),sx=s.x-dx/len*tail,sy=s.y-dy/len*tail;ctx.shadowColor=s.c;ctx.shadowBlur=17;
 if(s.m.t==='Fuoco'){for(let i=0;i<19;i++){let f=i/19,xx=sx+(s.x-sx)*f,yy=sy+(s.y-sy)*f+Math.sin(i*2+t*30)*6;flameShape(xx,yy,7+f*13,t+i)}for(let i=0;i<8;i++){let f=(t*2+i*.13)%1;rect(sx+(s.x-sx)*f+Math.sin(i*8+t)*13,sy+(s.y-sy)*f-12-i*2,3,3,'#ffe5a2')}}
 else if(s.m.t==='Elettro'){lightning(sx,sy,s.x,s.y,Math.floor(t*26),3);for(let i=0;i<4;i++){let a=t*5+i*1.57;line(s.x+Math.cos(a)*8,s.y+Math.sin(a)*8,s.x+Math.cos(a)*30,s.y+Math.sin(a)*30,'#fff6ab',2)}}
 else if(s.m.t==='Acqua'){ctx.lineCap='round';line(sx,sy,s.x,s.y,'#287dd488',s.r*1.7);for(let i=0;i<3;i++){ctx.beginPath();for(let j=0;j<18;j++){let f=j/17,w=Math.sin(t*21+j*.7+i*2)*7,xx=sx+(s.x-sx)*f-dy/len*w,yy=sy+(s.y-sy)*f+dx/len*w;j?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)}ctx.strokeStyle=['#4dbcf4','#8ae7ff','#e9fdff'][i];ctx.lineWidth=5-i;ctx.stroke()}ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.a);for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(-i*8,0,s.r+i*4,-1.25,1.25);ctx.strokeStyle=i===0?'#efffff':'#78d5f7';ctx.lineWidth=5-i;ctx.stroke()}ctx.restore();for(let i=0;i<10;i++){let a=t*5+i*2.4,r=12+(i%3)*7;ellipse(s.x+Math.cos(a)*r,s.y+Math.sin(a)*r,2,4,'#a9edff')}}
 else if(s.m.t==='Erba'&&s.m.mode!=='beam'){for(let i=0;i<7;i++){let f=i/7;leafShape(s.x-dx/len*i*9+Math.sin(t*12+i)*12,s.y-dy/len*i*9+Math.cos(t*12+i)*12,9+i%3,t*9+i)}line(sx,sy,s.x,s.y,'#a6e46155',3)}
 else if(s.m.mode==='beam'){line(sx,sy,s.x,s.y,s.c,25);line(sx,sy,s.x,s.y,'#efffe0',10);for(let i=0;i<7;i++){let f=i/7;ellipse(sx+dx/len*tail*f,sy+dy/len*tail*f,7,12,'#ffffff88')}}
 else if(s.m.t==='Ghiaccio'){line(sx,sy,s.x,s.y,'#86dce966',13);for(let i=0;i<8;i++){let x=s.x-dx/len*i*9,y=s.y-dy/len*i*9;poly([[x-5,y],[x,y-12],[x+5,y],[x,y+9]],i%2?'#b1efff':'#efffff','#64b9de')}}
 else if(s.m.mode==='slash'||s.m.mode==='dash'||s.m.t==='Volante'){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.a);for(let i=-1;i<2;i++){ctx.beginPath();ctx.moveTo(-35,i*13+13);ctx.quadraticCurveTo(0,i*13-18,30,i*13);ctx.strokeStyle=s.c;ctx.lineWidth=5;ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke()}ctx.restore()}
 else{let g=ctx.createRadialGradient(s.x,s.y,1,s.x,s.y,s.r*1.5);g.addColorStop(0,'#fff');g.addColorStop(.3,s.c);g.addColorStop(1,'#00000000');ctx.fillStyle=g;ctx.fillRect(s.x-s.r*2,s.y-s.r*2,s.r*4,s.r*4);for(let i=0;i<6;i++){let a=t*6+i;ellipse(s.x+Math.cos(a)*s.r,s.y+Math.sin(a)*s.r*.6,3,3,s.c)}}ctx.restore()}

// A light projectile stays compact; powerful streams expand into a sustained attack.
const originalDrawAttack=drawAttack;
drawAttack=function(s){let v=s.m.v||1,t=motionClock;ctx.save();
if(s.m.mode==='pellet'){ctx.shadowColor=s.c;ctx.shadowBlur=9*v;let r=10*v,dx=Math.cos(s.a),dy=Math.sin(s.a);if(s.m.t==='Fuoco'){for(let i=3;i>=0;i--)flameShape(s.x-dx*i*5*v,s.y-dy*i*5*v,r*(1-i*.18),t+i)}else if(s.m.t==='Acqua'){line(s.x-dx*23*v,s.y-dy*23*v,s.x,s.y,'#68dafa88',r*.8);ellipse(s.x,s.y,r,r*.7,'#289ee5');ellipse(s.x-2,s.y-2,r*.55,r*.35,'#bdfaff')}else if(s.m.t==='Elettro'){lightning(s.x-dx*30*v,s.y-dy*30*v,s.x,s.y,Math.floor(t*20),1);ellipse(s.x,s.y,r*.55,r*.55,'#fff8b0')}else{ellipse(s.x,s.y,r,r,s.c);ellipse(s.x-2,s.y-2,r*.45,r*.45,'#fff')}ctx.restore();return}
if(s.m.mode==='fireburst'){let r=23*v;ctx.shadowColor='#ff7a16';ctx.shadowBlur=23;for(let i=0;i<9;i++){let a=i*6.283/9+t*2;flameShape(s.x+Math.cos(a)*r*.6,s.y+Math.sin(a)*r*.6,12*v,t+i)}ellipse(s.x,s.y,r*.65,r*.65,'#fff4a5');for(let i=1;i<5;i++)flameShape(s.x-Math.cos(s.a)*i*15*v,s.y-Math.sin(s.a)*i*15*v,(12-i)*v,t+i);ctx.restore();return}
// Scale geometry around the projectile's current position, including its trail.
ctx.translate(s.x,s.y);ctx.scale(v,v);ctx.translate(-s.x,-s.y);originalDrawAttack({...s,r:s.r/v,ox:s.x+(s.ox-s.x)/v,oy:s.y+(s.oy-s.y)/v});ctx.restore()};
function drawBeam(b){let size=Math.min(b.len,b.age*1100),dx=Math.cos(b.a),dy=Math.sin(b.a),t=motionClock,v=b.m.v||1,x=b.ox+dx*size,y=b.oy+dy*size;ctx.save();ctx.lineCap='round';ctx.shadowColor=b.c;ctx.shadowBlur=14*v;
if(b.m.t==='Fuoco'){let count=Math.ceil(size/9);for(let i=0;i<count;i++){let q=i*9,f=q/Math.max(1,size),r=(5+f*17)*v,w=Math.sin(i*1.7+t*30)*r*.25;flameShape(b.ox+dx*q-dy*w,b.oy+dy*q+dx*w,r,t+i);if(v>1.3&&i%2===0)flameShape(b.ox+dx*q-dy*r*.6,b.oy+dy*q+dx*r*.6,r*.65,t-i)}line(b.ox,b.oy,x,y,'#fff4b0aa',3*v);for(let i=0;i<9*v;i++){let f=(t*1.7+i*.13)%1,w=Math.sin(i*8+t)*19*v;rect(b.ox+dx*size*f-dy*w,b.oy+dy*size*f+dx*w,2*v,2*v,'#ffe897')}}
else if(b.m.t==='Elettro'){lightning(b.ox,b.oy,x,y,Math.floor(t*25),3*v);if(v>1.3){for(let i=0;i<3;i++){let f=.3+i*.25,xx=b.ox+dx*size*f,yy=b.oy+dy*size*f;lightning(xx,yy,xx-dy*35*v,yy+dx*35*v,Math.floor(t*20)+i,1.5*v)}}}
else if(b.m.t==='Acqua'){line(b.ox,b.oy,x,y,'#208ddd88',30*v);line(b.ox,b.oy,x,y,'#219ee9',20*v);for(let k=0;k<4;k++){ctx.beginPath();for(let i=0;i<=28;i++){let q=size*i/28,w=Math.sin(i*.8-t*22+k*1.7)*5*v,xx=b.ox+dx*q-dy*w,yy=b.oy+dy*q+dx*w;i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)}ctx.strokeStyle=['#5addff','#d9ffff','#90eeff','#fff'][k];ctx.lineWidth=[7,3,4,1.5][k]*v;ctx.stroke()}for(let i=0;i<12*v;i++){let a=t*7+i*2.1;ellipse(x+Math.cos(a)*21*v,y+Math.sin(a)*21*v,2*v,3*v,'#e5fcff')}}
else if(b.m.t==='Ghiaccio'){line(b.ox,b.oy,x,y,'#92ddfa66',20*v);line(b.ox,b.oy,x,y,'#fff',6*v);for(let i=0;i<size/(17*v);i++){let xx=b.ox+dx*i*17*v,yy=b.oy+dy*i*17*v;ctx.save();ctx.translate(xx,yy);ctx.rotate(b.a+t*3+i);ctx.scale(v,v);poly([[-7,0],[0,-14],[7,0],[0,12]],i%2?'#fff':'#a3d8f0','#e9fdff');ctx.restore()}}
else{line(b.ox,b.oy,x,y,b.c,22*v);line(b.ox,b.oy,x,y,'#f4ffe7',7*v);for(let i=0;i<8*v;i++){let q=(t*220+i*27)%Math.max(1,size);ellipse(b.ox+dx*q,b.oy+dy*q,5*v,5*v,'#fff')}}ctx.restore()}
